const http = require('http');
const { URL } = require('url');
const dns = require('dns');
const net = require('net');

// Multi-tenant CLI tool that fetches resources on behalf of tenants
// Each tenant is isolated to their own allowed domains

const TENANT_CONFIGS = {
  'tenant-alpha': { allowedDomains: ['api.alpha-corp.com', 'cdn.alpha-corp.com'], internalNet: '10.0.1.0/24' },
  'tenant-beta': { allowedDomains: ['api.beta-inc.com'], internalNet: '10.0.2.0/24' },
};

const BLOCKED_RANGES = [
  { start: '10.0.0.0', end: '10.255.255.255' },
  { start: '172.16.0.0', end: '172.31.255.255' },
  { start: '192.168.0.0', end: '192.168.255.255' },
  { start: '127.0.0.0', end: '127.255.255.255' },
  { start: '169.254.0.0', end: '169.254.255.255' },
];

function ipToLong(ip) {
  return ip.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet, 10), 0) >>> 0;
}

function isBlockedIP(ip) {
  if (!net.isIPv4(ip)) return false;
  const ipLong = ipToLong(ip);
  for (const range of BLOCKED_RANGES) {
    const startLong = ipToLong(range.start);
    const endLong = ipToLong(range.end);
    if (ipLong >= startLong && ipLong <= endLong) {
      return true;
    }
  }
  return false;
}

function isDomainAllowed(hostname, tenantId) {
  const config = TENANT_CONFIGS[tenantId];
  if (!config) return false;
  return config.allowedDomains.includes(hostname);
}

async function resolveAndValidate(hostname) {
  return new Promise((resolve, reject) => {
    dns.resolve4(hostname, (err, addresses) => {
      if (err) return reject(new Error(`DNS resolution failed: ${err.message}`));
      if (!addresses || addresses.length === 0) return reject(new Error('No addresses found'));
      const blocked = addresses.find(addr => isBlockedIP(addr));
      if (blocked) {
        return reject(new Error(`Blocked IP detected: ${blocked}`));
      }
      resolve(addresses[0]);
    });
  });
}

class TenantResourceFetcher {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.config = TENANT_CONFIGS[tenantId];
    if (!this.config) throw new Error(`Unknown tenant: ${tenantId}`);
    this.resolvedCache = new Map();
  }

  async validateRequest(urlString) {
    let parsed;
    try {
      parsed = new URL(urlString);
    } catch (e) {
      throw new Error('Invalid URL');
    }

    if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
      throw new Error('Only HTTP(S) protocols allowed');
    }

    if (!isDomainAllowed(parsed.hostname, this.tenantId)) {
      throw new Error(`Domain ${parsed.hostname} not allowed for tenant ${this.tenantId}`);
    }

    // Pre-flight DNS check to prevent SSRF
    const resolvedIP = await resolveAndValidate(parsed.hostname);
    this.resolvedCache.set(parsed.hostname, resolvedIP);

    return parsed;
  }

  async fetch(urlString) {
    const validated = await this.validateRequest(urlString);

    // Use the hostname directly - the system trusts that DNS won't change
    // between validation and connection (standard pattern)
    return new Promise((resolve, reject) => {
      const options = {
        hostname: validated.hostname,
        port: validated.port || (validated.protocol === 'https:' ? 443 : 80),
        path: validated.pathname + validated.search,
        method: 'GET',
        headers: {
          'Host': validated.hostname,
          'X-Tenant-Id': this.tenantId,
          'User-Agent': 'TenantFetcher/1.0',
        },
        timeout: 5000,
      };

      const req = http.request(options, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve({ status: res.statusCode, body: data }));
      });

      req.on('error', reject);
      req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
      req.end();
    });
  }
}

// CLI entry point
async function main() {
  const [,, tenantId, url] = process.argv;
  if (!tenantId || !url) {
    console.error('Usage: node app.js <tenant-id> <url>');
    process.exit(1);
  }

  try {
    const fetcher = new TenantResourceFetcher(tenantId);
    const result = await fetcher.fetch(url);
    console.log(`Status: ${result.status}`);
    console.log(`Body: ${result.body.substring(0, 500)}`);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
}

main();

module.exports = { TenantResourceFetcher, isBlockedIP, resolveAndValidate };
